#####################################################################################
# Project: Coffee Rhizosphere Microbiome - 16S rRNA Metabarcoding
# Script: 07_environmental_analysis.R
# Author: Gustavo Goncalves
# Last edit: 18/11/2026
#
# Description:
# Analysis of associations between environmental variables and microbial
# community composition, including PCoA, envfit, dbRDA, permutation tests,
# and multicollinearity assessment.
#
# Notes:
#   This script requires the phyloseq object generated by 03_phyloseq_object.R.
#   Samples with missing environmental values are excluded from these analyses.
#####################################################################################

# Load project configuration
source("projects/coffee/config.R")

# Set up packages
library(phyloseq); packageVersion("phyloseq")
library(vegan); packageVersion("vegan")
library(ggplot2); packageVersion("ggplot2")

theme_set(theme_bw())

# Create environmental analysis directory
env_path <- file.path(results_path, "environmental_analysis")
dir.create(env_path, recursive = TRUE, showWarnings = FALSE)

# Load phyloseq object
ps <- readRDS(file.path(objects_path, "phyloseq_object.rds"))


#####################################################################################
# Environmental data
#####################################################################################

# Extract sample metadata
metadata <- data.frame(sample_data(ps))

# Select environmental variables
env <- metadata[
  ,
  c("pH", "Phosphorus", "Potassium", "CEC", "Altitude"),
  drop = FALSE
]

# Exclude samples with missing environmental values
complete.samples <- rownames(env)[complete.cases(env)]

ps <- prune_samples(complete.samples, ps)

# Remove taxa absent after sample filtering
ps <- prune_taxa(taxa_sums(ps) > 0, ps)

# Update metadata and environmental data
metadata <- data.frame(sample_data(ps))
env <- env[sample_names(ps), , drop = FALSE]

# Set random seed for permutation tests
set.seed(123)


#####################################################################################
# Bray-Curtis dissimilarity
#####################################################################################

bray <- phyloseq::distance(
  physeq = ps,
  method = "bray"
)

# Align metadata and environmental variables
metadata <- metadata[labels(bray), , drop = FALSE]
env <- env[labels(bray), , drop = FALSE]


#####################################################################################
# PCoA + envfit
#####################################################################################

# PCoA ordination
ord.pcoa <- ordinate(
  ps,
  method = "PCoA",
  distance = bray
)

# Extract PCoA scores
pcoa_scores <- as.data.frame(
  ord.pcoa$vectors[, 1:2, drop = FALSE]
)

colnames(pcoa_scores) <- c("Axis1", "Axis2")

# Align environmental data with PCoA scores
env.pcoa <- env[rownames(pcoa_scores), , drop = FALSE]

# Fit environmental variables onto PCoA ordination
ef <- envfit(
  pcoa_scores,
  env.pcoa,
  permutations = 999
)

print(ef)

# Extract envfit statistics
ef.table <- data.frame(
  Variable = names(ef$vectors$r),
  R2 = as.numeric(ef$vectors$r),
  Pvalue = as.numeric(ef$vectors$pvals)
)

# Save envfit statistics
write.csv(
  ef.table,
  file.path(env_path, "envfit_results.csv"),
  row.names = FALSE
)


#####################################################################################
# PCoA visualization with environmental vectors
#####################################################################################

# Extract environmental vector coordinates
ef.arrows <- as.data.frame(
  scores(ef, display = "vectors", choices = 1:2)
)

colnames(ef.arrows) <- c("Axis1", "Axis2")
ef.arrows$Variable <- rownames(ef.arrows)

# Scale arrows to fit the ordination
arrow.mult <- 0.7 * min(
  diff(range(pcoa_scores$Axis1)) /
    max(abs(ef.arrows$Axis1)),
  diff(range(pcoa_scores$Axis2)) /
    max(abs(ef.arrows$Axis2))
)

ef.arrows$Axis1 <- ef.arrows$Axis1 * arrow.mult
ef.arrows$Axis2 <- ef.arrows$Axis2 * arrow.mult

# Add sample metadata to PCoA scores
pcoa_scores$Sample <- rownames(pcoa_scores)

pcoa_scores <- merge(
  pcoa_scores,
  metadata,
  by.x = "Sample",
  by.y = "row.names",
  sort = FALSE
)

# PCoA with environmental vectors, colored by Farm
p1 <- ggplot(
  pcoa_scores,
  aes(
    x = Axis1,
    y = Axis2,
    color = Farm
  )
) +
  geom_point(size = 3) +
  geom_segment(
    data = ef.arrows,
    aes(
      x = 0,
      y = 0,
      xend = Axis1,
      yend = Axis2
    ),
    inherit.aes = FALSE,
    arrow = arrow(length = grid::unit(0.2, "cm")),
    color = "black",
    linewidth = 0.6
  ) +
  geom_text(
    data = ef.arrows,
    aes(
      x = Axis1,
      y = Axis2,
      label = Variable
    ),
    inherit.aes = FALSE,
    color = "black",
    size = 3.5,
    hjust = -0.1
  ) +
  labs(
    x = "PCoA 1",
    y = "PCoA 2",
    color = "Farm",
    title = "PCoA - Environmental variables"
  ) +
  coord_equal()

print(p1)

ggsave(
  filename = file.path(env_path, "pcoa_envfit.png"),
  plot = p1,
  width = 10,
  height = 8,
  dpi = 300
)


#####################################################################################
# Environmental associations - envfit R2
#####################################################################################

# Order environmental variables by R2
ef.table$Variable <- factor(
  ef.table$Variable,
  levels = ef.table$Variable[order(ef.table$R2)]
)

# Plot R2 values
p2 <- ggplot(
  ef.table,
  aes(
    x = Variable,
    y = R2
  )
) +
  geom_col(
    fill = "steelblue",
    color = "grey50",
    linewidth = 0.2
  ) +
  geom_text(
    aes(label = paste0("p = ", signif(Pvalue, 2))),
    hjust = -0.1,
    size = 3.5
  ) +
  coord_flip() +
  scale_y_continuous(
    limits = c(0, max(ef.table$R2) * 1.25)
  ) +
  labs(
    x = "Environmental variable",
    y = expression(R^2),
    title = "Environmental associations - envfit"
  )

print(p2)

ggsave(
  filename = file.path(env_path, "envfit_r2.png"),
  plot = p2,
  width = 9,
  height = 6,
  dpi = 300
)


#####################################################################################
# Distance-based redundancy analysis (dbRDA)
#####################################################################################

# Fit distance-based redundancy analysis
dbrda <- capscale(
  bray ~ pH + Phosphorus + Potassium + CEC + Altitude,
  data = env
)

print(dbrda)

# Global significance
anova.global <- anova(
  dbrda,
  permutations = 999
)

# Marginal effects
anova.margin <- anova(
  dbrda,
  by = "margin",
  permutations = 999
)

# Variance inflation factors
vif <- vif.cca(dbrda)

# R-squared
r2 <- RsquareAdj(dbrda)

# Display results
print(anova.global)
print(anova.margin)
print(vif)
print(r2)

# Save dbRDA statistics
write.csv(
  data.frame(
    Variable = names(vif),
    VIF = as.numeric(vif)
  ),
  file.path(env_path, "dbrda_vif.csv"),
  row.names = FALSE
)

write.csv(
  data.frame(
    R2 = r2$r.squared,
    Adjusted_R2 = r2$adj.r.squared
  ),
  file.path(env_path, "dbrda_r2.csv"),
  row.names = FALSE
)


#####################################################################################
# dbRDA visualization
#####################################################################################

# Extract site scores
dbrda.sites <- as.data.frame(
  scores(
    dbrda,
    display = "sites",
    choices = 1:2,
    scaling = 2
  )
)

colnames(dbrda.sites) <- c("Axis1", "Axis2")
dbrda.sites$Sample <- rownames(dbrda.sites)

# Add sample metadata
dbrda.sites <- merge(
  dbrda.sites,
  metadata,
  by.x = "Sample",
  by.y = "row.names",
  sort = FALSE
)

# Extract environmental biplot scores
dbrda.arrows <- as.data.frame(
  scores(
    dbrda,
    display = "bp",
    choices = 1:2,
    scaling = 2
  )
)

colnames(dbrda.arrows) <- c("Axis1", "Axis2")
dbrda.arrows$Variable <- rownames(dbrda.arrows)

# Scale arrows for visualization
arrow.mult.dbrda <- 0.7 * min(
  diff(range(dbrda.sites$Axis1)) /
    max(abs(dbrda.arrows$Axis1)),
  diff(range(dbrda.sites$Axis2)) /
    max(abs(dbrda.arrows$Axis2))
)

dbrda.arrows$Axis1 <- dbrda.arrows$Axis1 * arrow.mult.dbrda
dbrda.arrows$Axis2 <- dbrda.arrows$Axis2 * arrow.mult.dbrda

# dbRDA with environmental vectors
p3 <- ggplot(
  dbrda.sites,
  aes(
    x = Axis1,
    y = Axis2,
    color = Farm
  )
) +
  geom_point(size = 3) +
  geom_segment(
    data = dbrda.arrows,
    aes(
      x = 0,
      y = 0,
      xend = Axis1,
      yend = Axis2
    ),
    inherit.aes = FALSE,
    arrow = arrow(length = grid::unit(0.2, "cm")),
    color = "black",
    linewidth = 0.6
  ) +
  geom_text(
    data = dbrda.arrows,
    aes(
      x = Axis1,
      y = Axis2,
      label = Variable
    ),
    inherit.aes = FALSE,
    color = "black",
    size = 3.5,
    hjust = -0.1
  ) +
  labs(
    x = "dbRDA 1",
    y = "dbRDA 2",
    color = "Farm",
    title = "dbRDA - Environmental variables"
  ) +
  coord_equal()

print(p3)

ggsave(
  filename = file.path(env_path, "dbrda_environmental.png"),
  plot = p3,
  width = 10,
  height = 8,
  dpi = 300
)


#####################################################################################
# Environmental analysis report
#####################################################################################

report <- capture.output({

  cat("=====================================\n")
  cat("ENVIRONMENTAL ANALYSIS REPORT\n")
  cat("Project:", project_name, "\n")
  cat("=====================================\n\n")

  cat("Samples analyzed:", nsamples(ps), "\n")
  cat("Environmental variables:\n")
  cat(paste("-", colnames(env), collapse = "\n"))
  cat("\n\n")

  cat("ENVFIT\n")
  cat("-------------------------------------\n")
  print(ef.table)

  cat("\n\n")

  cat("dbRDA\n")
  cat("-------------------------------------\n")

  cat(
    "Variance explained:",
    round(100 * r2$r.squared, 2),
    "%\n"
  )

  cat(
    "Adjusted R2:",
    round(100 * r2$adj.r.squared, 2),
    "%\n\n"
  )

  cat("GLOBAL MODEL\n")
  cat("-------------------------------------\n")
  print(anova.global)

  cat("\nMARGINAL EFFECTS\n")
  cat("-------------------------------------\n")
  print(anova.margin)

  cat("\nMULTICOLLINEARITY (VIF)\n")
  cat("-------------------------------------\n")
  print(round(vif, 3))

  cat(
    "\nMaximum VIF:",
    round(max(vif), 3),
    "\n\n"
  )

  cat("INTERPRETATION\n")
  cat("-------------------------------------\n")

  if (anova.global$`Pr(>F)`[1] < 0.05) {
    cat("Global dbRDA model is significant.\n")
  } else {
    cat("Global dbRDA model is not significant.\n")
  }

  if (max(vif) < 5) {
    cat("No VIF values exceed 5.\n")
  } else {
    cat("One or more VIF values exceed 5.\n")
  }

  cat(
    "Environmental variables explain ",
    round(100 * r2$r.squared, 2),
    "% of the community variation (",
    round(100 * r2$adj.r.squared, 2),
    "% adjusted R2).\n",
    sep = ""
  )

})

# Save report
writeLines(
  report,
  file.path(env_path, "environmental_analysis_report.txt")
)

# Display report
cat(paste(report, collapse = "\n"))


#####################################################################################
# End
#####################################################################################
